import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"20、【觀】 坤下巽上","description":"溫公易說 - 20、【觀】 坤下巽上","frontmatter":{"title":"20、【觀】 坤下巽上","description":"溫公易說 - 20、【觀】 坤下巽上"},"headers":[],"relativePath":"classics/wengong/021.md","filePath":"classics/wengong/021.md"}'),l={name:"classics/wengong/021.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_20、【觀】-坤下巽上" tabindex="-1">20、【觀】 坤下巽上 <a class="header-anchor" href="#_20、【觀】-坤下巽上" aria-label="Permalink to “20、【觀】 坤下巽上”">​</a></h1><h3 id="彖曰-大觀在上-順而巽-中正以觀天下。觀盥而不薦-有孚顒若-下觀而化也。觀天之神道-而四時不忒。聖人以神道設教-而天下服矣。" tabindex="-1">彖曰：大觀在上，順而巽，中正以觀天下。觀盥而不薦，有孚顒若，下觀而化也。觀天之神道，而四時不忒。聖人以神道設教，而天下服矣。 <a class="header-anchor" href="#彖曰-大觀在上-順而巽-中正以觀天下。觀盥而不薦-有孚顒若-下觀而化也。觀天之神道-而四時不忒。聖人以神道設教-而天下服矣。" aria-label="Permalink to “彖曰：大觀在上，順而巽，中正以觀天下。觀盥而不薦，有孚顒若，下觀而化也。觀天之神道，而四時不忒。聖人以神道設教，而天下服矣。”">​</a></h3><p>觀者，上以德示人，使人觀而化之也。盥圭潔其德也，薦豐備其物也。顒，人君有德之容也。夫德由內出，物自外至。苟內德不充，雖外物豐備，不能化人也。故黍稷非馨，明德惟馨。苟有明信，澗溪沼沚之毛，蘋蘩薀藻之菜，可薦於鬼神，可羞於王公，而況下民乎？故曰盥而不薦。君人者，能隆內殺外，勤本略末，德潔誠著，物皆信之，然後可以不為而成，不言而化。恭已南面，顒然而已，所謂神道設教，而天下服也。故曰有孚顒若。</p><h3 id="象曰-風行地上-觀。先王以省方-觀民設教。" tabindex="-1">象曰：風行地上，觀。先王以省方，觀民設教。 <a class="header-anchor" href="#象曰-風行地上-觀。先王以省方-觀民設教。" aria-label="Permalink to “象曰：風行地上，觀。先王以省方，觀民設教。”">​</a></h3><p>先王省方，考禮樂，恊時日，飭法度，以示人為觀之象。</p><h3 id="初六-童觀-小人無咎-君子吝-象曰-初六童觀-小人道也。" tabindex="-1">初六：童觀，小人無咎，君子吝 象曰：初六童觀，小人道也。 <a class="header-anchor" href="#初六-童觀-小人無咎-君子吝-象曰-初六童觀-小人道也。" aria-label="Permalink to “初六：童觀，小人無咎，君子吝 象曰：初六童觀，小人道也。”">​</a></h3><h3 id="六二-窺觀-利女貞-象曰-窺觀女貞-亦可醜也。" tabindex="-1">六二：窺觀，利女貞 象曰：窺觀女貞，亦可醜也。 <a class="header-anchor" href="#六二-窺觀-利女貞-象曰-窺觀女貞-亦可醜也。" aria-label="Permalink to “六二：窺觀，利女貞 象曰：窺觀女貞，亦可醜也。”">​</a></h3><h3 id="六三-觀我生-進退-象曰-觀我生進退-未失道也。" tabindex="-1">六三：觀我生，進退 象曰：觀我生進退，未失道也。 <a class="header-anchor" href="#六三-觀我生-進退-象曰-觀我生進退-未失道也。" aria-label="Permalink to “六三：觀我生，進退 象曰：觀我生進退，未失道也。”">​</a></h3><h3 id="六四-觀國之光-利用賓於王-象曰-觀國之光-尚賓也。" tabindex="-1">六四：觀國之光，利用賓於王 象曰：觀國之光，尚賓也。 <a class="header-anchor" href="#六四-觀國之光-利用賓於王-象曰-觀國之光-尚賓也。" aria-label="Permalink to “六四：觀國之光，利用賓於王 象曰：觀國之光，尚賓也。”">​</a></h3><h3 id="九五-觀我生-君子無咎-象曰-觀我生-觀民也。" tabindex="-1">九五：觀我生，君子無咎 象曰：觀我生，觀民也。 <a class="header-anchor" href="#九五-觀我生-君子無咎-象曰-觀我生-觀民也。" aria-label="Permalink to “九五：觀我生，君子無咎 象曰：觀我生，觀民也。”">​</a></h3><h3 id="上九-觀其生-君子無咎-象曰-觀其生-志未平也。" tabindex="-1">上九：觀其生，君子無咎 象曰：觀其生，志未平也。 <a class="header-anchor" href="#上九-觀其生-君子無咎-象曰-觀其生-志未平也。" aria-label="Permalink to “上九：觀其生，君子無咎 象曰：觀其生，志未平也。”">​</a></h3>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
